using System.ComponentModel;

namespace BatchRenameStudio.Core;

/// <summary>Which part of the file name the steps operate on.</summary>
public enum ApplyTo
{
    /// <summary>Steps operate on the base name only (extension untouched).</summary>
    Name,
    /// <summary>Steps operate on the whole file name, extension included.</summary>
    NameAndExtension,
}

/// <summary>Processing order of the files. Also the order of <c>items</c> in the plan.</summary>
public enum SortMode
{
    /// <summary>Ordinal (codepoint) ascending, case sensitive.</summary>
    Name,
    Created,
    Modified,
}

public enum InsertPosition { Prefix, Suffix, Index }

public enum SequencePosition { Prefix, Suffix }

public enum CaseMode { Upper, Lower, Title }

public enum ExtensionMode { Lower, Upper, Set }

/// <summary>Raised for anything the caller can fix by editing rules.json.</summary>
public sealed class RuleException : Exception
{
    public RuleException(string message) : base(message) { }
    public RuleException(string message, Exception inner) : base(message, inner) { }
}

/// <summary>
/// One transformation. Concrete subclasses are mutable so the WinForms PropertyGrid
/// can edit them in place; <see cref="Clone"/> keeps preview/apply from sharing state.
/// </summary>
public abstract class RuleStep
{
    /// <summary>The <c>op</c> discriminator written to rules.json.</summary>
    [Browsable(false)]
    public abstract string Op { get; }

    /// <summary>Short human readable form, shown in the step list.</summary>
    public abstract string Describe();

    public abstract RuleStep Clone();

    public override string ToString() => Describe();
}

public sealed class ReplaceStep : RuleStep
{
    public override string Op => "replace";

    [Category("Replace"), Description("Text (or regular expression) to look for. An empty value makes the step a no-op.")]
    public string Find { get; set; } = "";

    [Category("Replace"), Description("Replacement text. In regex mode $1, $2 ... refer to capture groups.")]
    public string ReplaceWith { get; set; } = "";

    [Category("Replace"), Description("Treat Find as a .NET regular expression.")]
    public bool Regex { get; set; }

    [Category("Replace"), Description("Case insensitive matching (applies to literal and regex mode alike).")]
    public bool IgnoreCase { get; set; }

    public override string Describe()
        => $"replace  \"{Find}\" -> \"{ReplaceWith}\"{(Regex ? "  [regex]" : "")}{(IgnoreCase ? "  [ignore case]" : "")}";

    public override RuleStep Clone() => new ReplaceStep
    {
        Find = Find,
        ReplaceWith = ReplaceWith,
        Regex = Regex,
        IgnoreCase = IgnoreCase,
    };
}

public sealed class InsertStep : RuleStep
{
    public override string Op => "insert";

    [Category("Insert"), Description("Text to insert.")]
    public string Text { get; set; } = "";

    [Category("Insert"), Description("Prefix = before the target, Suffix = after it, Index = at a 0-based position.")]
    public InsertPosition Position { get; set; } = InsertPosition.Prefix;

    [Category("Insert"), Description("0-based insertion point, used when Position is Index. Clamped to the target length.")]
    public int Index { get; set; }

    public override string Describe()
        => $"insert  \"{Text}\" at {Position.ToString().ToLowerInvariant()}{(Position == InsertPosition.Index ? " " + Index : "")}";

    public override RuleStep Clone() => new InsertStep { Text = Text, Position = Position, Index = Index };
}

public sealed class RemoveStep : RuleStep
{
    public override string Op => "remove";

    [Category("Remove"), Description("0-based start position. Clamped to the target length.")]
    public int From { get; set; }

    [Category("Remove"), Description("How many characters to remove. Clamped to what is left after From.")]
    public int Count { get; set; }

    public override string Describe() => $"remove  {Count} char(s) from {From}";

    public override RuleStep Clone() => new RemoveStep { From = From, Count = Count };
}

public sealed class SequenceStep : RuleStep
{
    public override string Op => "sequence";

    [Category("Sequence"), Description(@"Literal text plus one {n:PAD} token, where PAD is zero padding, e.g. ""{n:000}_"".")]
    public string Pattern { get; set; } = "{n:000}_";

    [Category("Sequence"), Description("Counter value for the first file in processing order.")]
    public int Start { get; set; } = 1;

    [Category("Sequence"), Description("Added to the counter for every file, whatever that file's final status is.")]
    public int Step { get; set; } = 1;

    [Category("Sequence"), Description("Where the rendered pattern goes.")]
    public SequencePosition Position { get; set; } = SequencePosition.Prefix;

    public override string Describe()
        => $"sequence  \"{Pattern}\" as {Position.ToString().ToLowerInvariant()}, start {Start} step {Step}";

    public override RuleStep Clone() => new SequenceStep
    {
        Pattern = Pattern,
        Start = Start,
        Step = Step,
        Position = Position,
    };
}

public sealed class CaseStep : RuleStep
{
    public override string Op => "case";

    [Category("Case"), Description("Title = first letter of every letter run upper, the rest lower.")]
    public CaseMode Mode { get; set; } = CaseMode.Lower;

    public override string Describe() => $"case  {Mode.ToString().ToLowerInvariant()}";

    public override RuleStep Clone() => new CaseStep { Mode = Mode };
}

public sealed class ExtensionStep : RuleStep
{
    public override string Op => "extension";

    [Category("Extension"), Description("Always applies to the extension, whatever Apply To says.")]
    public ExtensionMode Mode { get; set; } = ExtensionMode.Lower;

    [Category("Extension"), Description("New extension, without the leading dot. Used when Mode is Set.")]
    public string Value { get; set; } = "";

    public override string Describe()
        => $"extension  {Mode.ToString().ToLowerInvariant()}{(Mode == ExtensionMode.Set ? " \"" + Value + "\"" : "")}";

    public override RuleStep Clone() => new ExtensionStep { Mode = Mode, Value = Value };
}

/// <summary>A complete rule set: the contents of rules.json.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;

    public SortMode Sort { get; set; } = SortMode.Name;

    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var s in Steps) copy.Steps.Add(s.Clone());
        return copy;
    }
}

