namespace BatchRenameStudio.Core;

/// <summary>The four statuses of the fixed output contract.</summary>
public static class PlanStatus
{
    public const string Ok = "ok";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Invalid = "invalid";
}

/// <summary>A file on disk, as fed into the engine. Timestamps are UTC.</summary>
public sealed class SourceFile
{
    public SourceFile(string name, DateTime createdUtc, DateTime modifiedUtc)
    {
        Name = name;
        CreatedUtc = createdUtc;
        ModifiedUtc = modifiedUtc;
    }

    public string Name { get; }
    public DateTime CreatedUtc { get; }
    public DateTime ModifiedUtc { get; }
}

public sealed class PlanItem
{
    public PlanItem(string original, string proposed, string status, string reason)
    {
        Original = original;
        Proposed = proposed;
        Status = status;
        Reason = reason;
    }

    public string Original { get; }
    public string Proposed { get; }
    public string Status { get; }
    public string Reason { get; }

    public bool IsRenamable => Status == PlanStatus.Ok;
}

public sealed class PlanSummary
{
    public int Total { get; init; }
    public int Ok { get; init; }
    public int Collision { get; init; }
    public int Unchanged { get; init; }
    public int Invalid { get; init; }

    /// <summary>The single line the headless mode prints to stdout.</summary>
    public string ToSummaryLine()
        => $"total={Total} ok={Ok} collision={Collision} unchanged={Unchanged} invalid={Invalid}";
}

public sealed class PlanDocument
{
    public const int CurrentSchemaVersion = 1;

    public PlanDocument(IReadOnlyList<PlanItem> items, PlanSummary summary)
    {
        Items = items;
        Summary = summary;
    }

    public int SchemaVersion => CurrentSchemaVersion;
    public IReadOnlyList<PlanItem> Items { get; }
    public PlanSummary Summary { get; }
}

