using System.Globalization;

namespace BatchRenameStudio.Core;

/// <summary>A file name split into base and extension. The extension never carries the dot.</summary>
public readonly struct NameParts
{
    public NameParts(string baseName, string extension)
    {
        Base = baseName;
        Extension = extension;
    }

    public string Base { get; }
    public string Extension { get; }

    /// <summary>Reassembly per contract rule 12.</summary>
    public string Join() => Extension.Length == 0 ? Base : Base + "." + Extension;
}

/// <summary>
/// Name splitting, reassembly and validity — the literal reading of contract rules 2, 12 and 13.
/// </summary>
public static class NameRules
{
    /// <summary>Characters that make a proposed name invalid (plus everything below U+0020).</summary>
    public static readonly char[] InvalidCharacters = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    public const int MaxNameLength = 255;

    private static readonly HashSet<string> ReservedDeviceNames = BuildReservedNames();

    private static HashSet<string> BuildReservedNames()
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "CON", "PRN", "AUX", "NUL" };
        for (int i = 1; i <= 9; i++)
        {
            set.Add("COM" + i.ToString(CultureInfo.InvariantCulture));
            set.Add("LPT" + i.ToString(CultureInfo.InvariantCulture));
        }
        return set;
    }

    /// <summary>
    /// Contract rule 2: let <c>dot</c> be the index of the LAST '.'; if <c>dot &gt; 0</c> the name splits
    /// there, otherwise the whole name is the base and the extension is empty.
    /// </summary>
    public static NameParts Split(string name)
    {
        int dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            return new NameParts(name.Substring(0, dot), name.Substring(dot + 1));
        }
        return new NameParts(name, "");
    }

    public static bool IsReservedDeviceName(string baseName) => ReservedDeviceNames.Contains(baseName);

    /// <summary>
    /// Contract rule 13, first bullet. Returns <c>true</c> when the name cannot be used,
    /// with a short human readable reason.
    /// </summary>
    public static bool IsInvalidName(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "empty name";
            return true;
        }

        if (proposed.Length > MaxNameLength)
        {
            reason = $"name is {proposed.Length} characters, limit is {MaxNameLength}";
            return true;
        }

        foreach (char c in proposed)
        {
            if (c < ' ')
            {
                reason = $"control character U+{(int)c:X4}";
                return true;
            }
            if (Array.IndexOf(InvalidCharacters, c) >= 0)
            {
                reason = $"illegal character '{c}'";
                return true;
            }
        }

        var parts = Split(proposed);
        if (IsReservedDeviceName(parts.Base))
        {
            reason = $"reserved device name '{parts.Base}'";
            return true;
        }

        reason = "";
        return false;
    }
}

