using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>
/// The whole of the naming contract in one place: sorting, step application, status assignment.
/// Pure — it never touches the file system, so the GUI preview and the headless plan are the
/// same computation over the same inputs.
/// </summary>
public static class RenameEngine
{
    /// <summary>Guards against catastrophic backtracking in a user supplied pattern.</summary>
    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);

    /// <summary>Matches the one <c>{n:PAD}</c> token a sequence pattern may contain.</summary>
    private static readonly Regex SequenceToken =
        new(@"\{n:(0+)\}", RegexOptions.CultureInvariant, RegexTimeout);

    /// <summary>Builds the plan for <paramref name="files"/> under <paramref name="rules"/>.</summary>
    /// <exception cref="RuleException">The rule set cannot be executed (e.g. a malformed regex).</exception>
    public static PlanDocument BuildPlan(IEnumerable<SourceFile> files, RuleSet rules)
    {
        var ordered = Sort(files, rules.Sort);

        // Compiled once per plan, not once per file: an invalid regex must fail the whole run.
        var compiled = rules.Steps.Select(CompileStep).ToList();

        var proposals = new string[ordered.Count];
        for (int i = 0; i < ordered.Count; i++)
        {
            proposals[i] = ComputeProposedName(ordered[i].Name, rules.ApplyTo, compiled, i);
        }

        var items = Classify(ordered, proposals);
        return new PlanDocument(items, Summarize(items));
    }

    /// <summary>Contract rule 5. Ties fall back to the ordinal name so the output stays deterministic.</summary>
    public static IReadOnlyList<SourceFile> Sort(IEnumerable<SourceFile> files, SortMode mode)
    {
        var list = files.ToList();
        list.Sort((a, b) =>
        {
            int cmp = mode switch
            {
                SortMode.Created => a.CreatedUtc.CompareTo(b.CreatedUtc),
                SortMode.Modified => a.ModifiedUtc.CompareTo(b.ModifiedUtc),
                _ => 0,
            };
            return cmp != 0 ? cmp : string.CompareOrdinal(a.Name, b.Name);
        });
        return list;
    }

    /// <summary>Applies every step to one file. <paramref name="fileIndex"/> is 0-based processing order.</summary>
    public static string ComputeProposedName(string originalName, ApplyTo applyTo, IEnumerable<CompiledStep> steps, int fileIndex)
    {
        if (applyTo == ApplyTo.NameAndExtension)
        {
            // Contract rule 3/12: the target string IS the whole name, and an extension step
            // re-splits the current working string and rewrites its trailing extension.
            string whole = originalName;
            foreach (var step in steps)
            {
                if (step.Extension is { } ext)
                {
                    var parts = NameRules.Split(whole);
                    whole = new NameParts(parts.Base, ApplyExtension(parts.Extension, ext)).Join();
                }
                else
                {
                    whole = step.Apply(whole, fileIndex);
                }
            }
            return whole;
        }

        var split = NameRules.Split(originalName);
        string baseName = split.Base;
        string extension = split.Extension;
        foreach (var step in steps)
        {
            if (step.Extension is { } ext)
            {
                extension = ApplyExtension(extension, ext);
            }
            else
            {
                baseName = step.Apply(baseName, fileIndex);
            }
        }
        return new NameParts(baseName, extension).Join();
    }

    /// <summary>Contract rule 13 + 14: status per item, in processing order.</summary>
    private static List<PlanItem> Classify(IReadOnlyList<SourceFile> ordered, string[] proposals)
    {
        // Case-insensitive occupancy of the folder, and of everything being proposed.
        var existingCount = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        var proposedCount = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var f in ordered) Bump(existingCount, f.Name);
        foreach (var p in proposals) Bump(proposedCount, p);

        var items = new List<PlanItem>(ordered.Count);
        for (int i = 0; i < ordered.Count; i++)
        {
            string original = ordered[i].Name;
            string proposed = proposals[i];

