            // "an existing file other than this item" — discount this item's own original.
            int existingHits = Count(existingCount, proposed);
            if (string.Equals(proposed, original, StringComparison.OrdinalIgnoreCase)) existingHits--;

            // "another item's proposed name" — discount this item's own proposal.
            int proposedHits = Count(proposedCount, proposed) - 1;

            if (existingHits > 0 || proposedHits > 0)
            {
                string reason = existingHits > 0 && proposedHits > 0
                    ? "target already exists and is also claimed by another item"
                    : existingHits > 0
                        ? "target already exists in the folder"
                        : "another item proposes the same name";
                items.Add(new PlanItem(original, proposed, PlanStatus.Collision, reason));
                continue;
            }

            if (string.Equals(proposed, original, StringComparison.Ordinal))
