            {
                regex = new Regex(step.Find, options, RegexTimeout);
            }
            catch (ArgumentException ex)
            {
                throw new RuleException($"Invalid regular expression \"{step.Find}\": {ex.Message}", ex);
            }
            return CompiledStep.FromTransform((s, _) =>
            {
                try
                {
                    return regex.Replace(s, step.ReplaceWith);
                }
                catch (RegexMatchTimeoutException)
                {
