        return CompiledStep.FromTransform((s, _) => ReplaceLiteral(s, step.Find, step.ReplaceWith, comparison));
    }

    /// <summary>Replaces every occurrence. Literal mode never interprets $1 in the replacement.</summary>
    private static string ReplaceLiteral(string input, string find, string replaceWith, StringComparison comparison)
    {
        var sb = new StringBuilder(input.Length);
        int pos = 0;
        while (true)
        {
            int hit = input.IndexOf(find, pos, comparison);
            if (hit < 0) break;
            sb.Append(input, pos, hit - pos).Append(replaceWith);
            pos = hit + find.Length;
        }
        sb.Append(input, pos, input.Length - pos);
        return sb.ToString();
    }

    private static string ApplyInsert(string target, InsertStep step) => step.Position switch
    {
        InsertPosition.Prefix => step.Text + target,
        InsertPosition.Suffix => target + step.Text,
        _ => target.Insert(Math.Clamp(step.Index, 0, target.Length), step.Text),
    };

    private static string ApplyRemove(string target, RemoveStep step)
    {
        int from = Math.Clamp(step.From, 0, target.Length);
        int count = Math.Clamp(step.Count, 0, target.Length - from);
        return count == 0 ? target : target.Remove(from, count);
    }

    /// <summary>Contract rule 9. The counter is index based, so status never shifts it.</summary>
    public static string RenderSequence(SequenceStep step, int fileIndex)
    {
        long value = (long)step.Start + (long)step.Step * fileIndex;
        return SequenceToken.Replace(step.Pattern, m =>
        {
            int width = m.Groups[1].Value.Length;
            return value.ToString("D" + width.ToString(CultureInfo.InvariantCulture), CultureInfo.InvariantCulture);
        });
    }

    /// <summary>Contract rule 10.</summary>
    public static string ApplyCase(string target, CaseMode mode)
    {
        switch (mode)
        {
            case CaseMode.Upper:
                return target.ToUpperInvariant();
            case CaseMode.Lower:
                return target.ToLowerInvariant();
            default:
                {
                    var sb = new StringBuilder(target.Length);
                    bool inRun = false;
                    foreach (char c in target)
                    {
                        if (char.IsLetter(c))
                        {
                            sb.Append(inRun ? char.ToLowerInvariant(c) : char.ToUpperInvariant(c));
                            inRun = true;
                        }
                        else
                        {
                            sb.Append(c);
                            inRun = false;
                        }
                    }
                    return sb.ToString();
                }
        }
    }

    /// <summary>Contract rule 11. <paramref name="extension"/> never carries the dot.</summary>
    public static string ApplyExtension(string extension, ExtensionStep step) => step.Mode switch
    {
        ExtensionMode.Upper => extension.ToUpperInvariant(),
        ExtensionMode.Lower => extension.ToLowerInvariant(),
        _ => step.Value,
    };
}

