using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Unicode;

namespace BatchRenameStudio.Core;

/// <summary>
/// Reader and writer for rules.json. Parsing is hand rolled on JsonDocument: the step array is
/// polymorphic on <c>op</c>, optional members need contract defaults, and an unknown <c>op</c> or
/// mode must be a loud error rather than a silently skipped step.
/// </summary>
public static class RulesJson
{
    private static readonly JsonDocumentOptions ReaderOptions = new()
    {
        AllowTrailingCommas = true,
        CommentHandling = JsonCommentHandling.Skip,
    };

    public static RuleSet Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            throw new RuleException($"Cannot read rules file \"{path}\": {ex.Message}", ex);
        }
        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json, ReaderOptions);
        }
        catch (JsonException ex)
        {
            throw new RuleException($"rules.json is not valid JSON: {ex.Message}", ex);
        }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                throw new RuleException("rules.json must contain a JSON object at the top level.");
            }

            var rules = new RuleSet
            {
                ApplyTo = ParseEnum(GetString(root, "applyTo"), "applyTo", ApplyTo.Name,
                    ("name", ApplyTo.Name), ("nameandextension", ApplyTo.NameAndExtension)),
                Sort = ParseEnum(GetString(root, "sort"), "sort", SortMode.Name,
                    ("name", SortMode.Name), ("created", SortMode.Created), ("modified", SortMode.Modified)),
            };

            if (root.TryGetProperty("steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                {
                    throw new RuleException("\"steps\" must be an array.");
                }
                int index = 0;
                foreach (var element in steps.EnumerateArray())
                {
                    rules.Steps.Add(ParseStep(element, index));
                    index++;
                }
            }

            return rules;
        }
    }

    private static RuleStep ParseStep(JsonElement element, int index)
    {
        if (element.ValueKind != JsonValueKind.Object)
        {
            throw new RuleException($"steps[{index}] must be an object.");
        }

        string op = (GetString(element, "op") ?? throw new RuleException($"steps[{index}] has no \"op\".")).Trim();
        switch (op.ToLowerInvariant())
        {
            case "replace":
                return new ReplaceStep
                {
                    Find = GetString(element, "find") ?? "",
                    ReplaceWith = GetString(element, "replaceWith") ?? "",
                    Regex = GetBool(element, "regex", false),
                    IgnoreCase = GetBool(element, "ignoreCase", false),
                };

            case "insert":
                return new InsertStep
                {
                    Text = GetString(element, "text") ?? "",
                    Position = ParseEnum(GetString(element, "position"), $"steps[{index}].position", InsertPosition.Prefix,
                        ("prefix", InsertPosition.Prefix), ("suffix", InsertPosition.Suffix), ("index", InsertPosition.Index)),
                    Index = GetInt(element, "index", 0),
                };

            case "remove":
                return new RemoveStep
                {
                    From = GetInt(element, "from", 0),
                    Count = GetInt(element, "count", 0),
                };

            case "sequence":
                return new SequenceStep
                {
                    Pattern = GetString(element, "pattern") ?? "{n:000}",
                    Start = GetInt(element, "start", 1),
                    Step = GetInt(element, "step", 1),
                    Position = ParseEnum(GetString(element, "position"), $"steps[{index}].position", SequencePosition.Prefix,
                        ("prefix", SequencePosition.Prefix), ("suffix", SequencePosition.Suffix)),
                };

            case "case":
                return new CaseStep
                {
                    Mode = ParseEnum(GetString(element, "mode"), $"steps[{index}].mode", CaseMode.Lower,
                        ("upper", CaseMode.Upper), ("lower", CaseMode.Lower), ("title", CaseMode.Title)),
                };

            case "extension":
                return new ExtensionStep
                {
                    Mode = ParseEnum(GetString(element, "mode"), $"steps[{index}].mode", ExtensionMode.Lower,
                        ("lower", ExtensionMode.Lower), ("upper", ExtensionMode.Upper), ("set", ExtensionMode.Set)),
                    Value = GetString(element, "value") ?? "",
                };

            default:
                throw new RuleException($"steps[{index}] has unknown op \"{op}\".");
        }
    }

    // ------------------------------------------------------------- writing

    /// <summary>Serialises a rule set back into the exact shape of the input contract.</summary>
    public static string Serialize(RuleSet rules)
    {
        var options = new JsonWriterOptions
        {
            Indented = true,
            Encoder = JavaScriptEncoder.Create(UnicodeRanges.All),
        };

        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, options))
        {
            writer.WriteStartObject();
            writer.WriteString("applyTo", rules.ApplyTo == ApplyTo.NameAndExtension ? "nameAndExtension" : "name");
            writer.WriteString("sort", rules.Sort.ToString().ToLowerInvariant());
            writer.WriteStartArray("steps");
            foreach (var step in rules.Steps)
            {
                writer.WriteStartObject();
                writer.WriteString("op", step.Op);
                switch (step)
                {
                    case ReplaceStep r:
                        writer.WriteString("find", r.Find);
                        writer.WriteString("replaceWith", r.ReplaceWith);
                        writer.WriteBoolean("regex", r.Regex);
                        writer.WriteBoolean("ignoreCase", r.IgnoreCase);
                        break;
                    case InsertStep i:
                        writer.WriteString("text", i.Text);
                        writer.WriteString("position", i.Position.ToString().ToLowerInvariant());
                        writer.WriteNumber("index", i.Index);
                        break;
                    case RemoveStep rm:
                        writer.WriteNumber("from", rm.From);
                        writer.WriteNumber("count", rm.Count);
                        break;
                    case SequenceStep s:
                        writer.WriteString("pattern", s.Pattern);
                        writer.WriteNumber("start", s.Start);
                        writer.WriteNumber("step", s.Step);
                        writer.WriteString("position", s.Position.ToString().ToLowerInvariant());
                        break;
                    case CaseStep c:
                        writer.WriteString("mode", c.Mode.ToString().ToLowerInvariant());
                        break;
                    case ExtensionStep e:
                        writer.WriteString("mode", e.Mode.ToString().ToLowerInvariant());
                        writer.WriteString("value", e.Value);
                        break;
                }
                writer.WriteEndObject();
            }
            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        return JsonText.Normalize(Encoding.UTF8.GetString(stream.ToArray()));
    }

    public static void Save(string path, RuleSet rules) => JsonText.WriteUtf8NoBom(path, Serialize(rules));

    // ------------------------------------------------------------- helpers

    private static string? GetString(JsonElement parent, string name)
    {
        if (!parent.TryGetProperty(name, out var value)) return null;
        return value.ValueKind switch
        {
            JsonValueKind.String => value.GetString(),
            JsonValueKind.Null => null,
            JsonValueKind.Number => value.ToString(),
            _ => throw new RuleException($"\"{name}\" must be a string."),
        };
    }

    private static bool GetBool(JsonElement parent, string name, bool fallback)
    {
        if (!parent.TryGetProperty(name, out var value)) return fallback;
        return value.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            JsonValueKind.Null => fallback,
            _ => throw new RuleException($"\"{name}\" must be true or false."),
        };
    }

    private static int GetInt(JsonElement parent, string name, int fallback)
    {
        if (!parent.TryGetProperty(name, out var value)) return fallback;
        if (value.ValueKind == JsonValueKind.Null) return fallback;
        if (value.ValueKind == JsonValueKind.Number && value.TryGetInt32(out int n)) return n;
        if (value.ValueKind == JsonValueKind.String && int.TryParse(value.GetString(), out int parsed)) return parsed;
        throw new RuleException($"\"{name}\" must be a 32-bit integer.");
    }

    private static T ParseEnum<T>(string? raw, string what, T fallback, params (string Key, T Value)[] map)
    {
        if (string.IsNullOrWhiteSpace(raw)) return fallback;
        string key = raw.Trim().ToLowerInvariant();
        foreach (var (k, v) in map)
        {
            if (k == key) return v;
        }
        throw new RuleException($"\"{what}\" has unsupported value \"{raw}\". Expected one of: {string.Join(", ", map.Select(m => m.Key))}.");
    }
}

