using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>
/// Byte level guarantees for everything this tool writes: UTF-8 without a BOM, LF line endings,
/// so the same inputs always give a byte identical file (contract rule 15).
/// </summary>
public static class JsonText
{
    private static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

    /// <summary>
    /// Forces LF. Utf8JsonWriter indents with Environment.NewLine on .NET 8, which would make the
    /// output platform dependent; only the indentation is touched, escaped \r\n inside strings is
    /// already backslash text and cannot match.
    /// </summary>
    public static string Normalize(string json) => json.Replace("\r\n", "\n").Replace("\r", "\n");

    public static void WriteUtf8NoBom(string path, string text)
    {
        string? dir = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
        File.WriteAllText(path, text, Utf8NoBom);
    }
}

