namespace BatchRenameStudio.Core;

/// <summary>Reads the working folder. Contract rule 1: regular files, directly inside, non-recursive.</summary>
public static class FileScanner
{
    public static IReadOnlyList<SourceFile> Scan(string directory)
    {
        DirectoryInfo info;
        try
        {
            info = new DirectoryInfo(directory);
        }
        catch (Exception ex) when (ex is ArgumentException or NotSupportedException or PathTooLongException)
        {
            throw new RuleException($"\"{directory}\" is not a usable folder path: {ex.Message}", ex);
        }

        if (!info.Exists)
        {
            throw new RuleException($"Folder not found: \"{directory}\".");
        }

        var files = new List<SourceFile>();
        foreach (var file in info.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            // EnumerateFiles already excludes directories; re-check in case of a reparse point
            // that resolves to one.
            if ((file.Attributes & FileAttributes.Directory) != 0) continue;
            files.Add(new SourceFile(file.Name, file.CreationTimeUtc, file.LastWriteTimeUtc));
        }
        return files;
    }
}

