using System.Globalization;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Text.Unicode;

namespace BatchRenameStudio.Core;

/// <summary>One completed rename, in the direction it was performed.</summary>
public sealed class RenameOperation
{
    public RenameOperation(string from, string to)
    {
        From = from;
        To = to;
    }

    public string From { get; }
    public string To { get; }
}

/// <summary>Everything one Apply did, and therefore everything an Undo has to walk back.</summary>
public sealed class RenameBatch
{
    public RenameBatch(string directory, DateTime timestampUtc, IReadOnlyList<RenameOperation> operations)
    {
        Directory = directory;
        TimestampUtc = timestampUtc;
        Operations = operations;
    }

    public string Directory { get; }
    public DateTime TimestampUtc { get; }
    public IReadOnlyList<RenameOperation> Operations { get; }

    public string Label =>
        $"{TimestampUtc.ToLocalTime():HH:mm:ss} — {Operations.Count} file(s) in {System.IO.Path.GetFileName(Directory.TrimEnd(System.IO.Path.DirectorySeparatorChar))}";
}

public sealed class RenameOutcome
{
    public RenameBatch? Batch { get; init; }
    public List<string> Errors { get; } = new();
    public int Renamed => Batch?.Operations.Count ?? 0;
    public int Skipped { get; set; }
}

/// <summary>
/// Performs the renames the plan marked <c>ok</c>, and can walk them back.
/// Nothing else in the plan is ever touched — collision/invalid/unchanged items are left alone.
/// </summary>
public static class RenameExecutor
{
    /// <summary>Applies the ok items of <paramref name="plan"/> inside <paramref name="directory"/>.</summary>
    public static RenameOutcome Apply(string directory, PlanDocument plan, DateTime nowUtc)
    {
        var done = new List<RenameOperation>();
        var errors = new List<string>();
        int skipped = 0;

        foreach (var item in plan.Items)
        {
            if (!item.IsRenamable)
            {
                skipped++;
                continue;
            }

            string from = Path.Combine(directory, item.Original);
            string to = Path.Combine(directory, item.Proposed);

            try
            {
                MoveFile(from, to);
                done.Add(new RenameOperation(item.Original, item.Proposed));
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
            {
                errors.Add($"{item.Original} -> {item.Proposed}: {ex.Message}");
            }
        }

        var batch = new RenameBatch(directory, nowUtc, done);
        var result = new RenameOutcome { Batch = batch, Skipped = skipped };
        result.Errors.AddRange(errors);

        if (done.Count > 0)
        {
            TryWriteJournal(batch, result.Errors);
        }
        return result;
    }

    /// <summary>Reverses a batch, newest operation first.</summary>
    public static RenameOutcome Undo(RenameBatch batch)
    {
        var undone = new List<RenameOperation>();
        var result = new RenameOutcome();

        for (int i = batch.Operations.Count - 1; i >= 0; i--)
        {
            var op = batch.Operations[i];
            string from = Path.Combine(batch.Directory, op.To);
            string to = Path.Combine(batch.Directory, op.From);
            try
            {
                if (!File.Exists(from))
                {
                    result.Errors.Add($"{op.To}: file is gone, cannot undo");
                    continue;
                }
                MoveFile(from, to);
                undone.Add(new RenameOperation(op.To, op.From));
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
            {
                result.Errors.Add($"{op.To} -> {op.From}: {ex.Message}");
            }
        }

        return new RenameOutcome { Batch = new RenameBatch(batch.Directory, batch.TimestampUtc, undone) }
            .WithErrors(result.Errors);
    }

    private static RenameOutcome WithErrors(this RenameOutcome outcome, IEnumerable<string> errors)
    {
        outcome.Errors.AddRange(errors);
        return outcome;
    }

    /// <summary>
    /// File.Move refuses a destination that "already exists" when the two paths differ only in
    /// case, so a case-only rename goes through a unique temporary name.
    /// </summary>
    private static void MoveFile(string from, string to)
    {
        if (string.Equals(from, to, StringComparison.Ordinal)) return;

        if (string.Equals(from, to, StringComparison.OrdinalIgnoreCase))
        {
            string temp = MakeTempPath(from);
            File.Move(from, temp);
            try
            {
                File.Move(temp, to);
            }
            catch
            {
                // Put it back rather than leaving a stray .brs-tmp file behind.
                try { File.Move(temp, from); } catch { /* nothing better to do */ }
                throw;
            }
            return;
        }

        File.Move(from, to);
    }

    private static string MakeTempPath(string path)
    {
        string dir = Path.GetDirectoryName(path) ?? "";
        for (int i = 0; ; i++)
        {
            string candidate = Path.Combine(dir, $"~brs-{Guid.NewGuid():N}-{i}.tmp");
            if (!File.Exists(candidate)) return candidate;
        }
    }

    // ------------------------------------------------------------- journal

    /// <summary>Where crash recovery information goes. Best effort: a failure here never fails a rename.</summary>
    public static string JournalDirectory => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "BatchRenameStudio", "history");

    private static void TryWriteJournal(RenameBatch batch, List<string> errors)
    {
        try
        {
            Directory.CreateDirectory(JournalDirectory);
            string name = batch.TimestampUtc.ToString("yyyyMMdd'T'HHmmss'Z'", CultureInfo.InvariantCulture)
                          + "-" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".json";
            JsonText.WriteUtf8NoBom(Path.Combine(JournalDirectory, name), SerializeJournal(batch));
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            errors.Add($"(rename succeeded, history file not written: {ex.Message})");
        }
    }

    private static string SerializeJournal(RenameBatch batch)
    {
        var options = new JsonWriterOptions { Indented = true, Encoder = JavaScriptEncoder.Create(UnicodeRanges.All) };
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, options))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", 1);
            writer.WriteString("directory", batch.Directory);
            writer.WriteString("timestampUtc", batch.TimestampUtc.ToString("O", CultureInfo.InvariantCulture));
            writer.WriteStartArray("operations");
            foreach (var op in batch.Operations)
            {
                writer.WriteStartObject();
                writer.WriteString("from", op.From);
                writer.WriteString("to", op.To);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();
            writer.WriteEndObject();
        }
        return JsonText.Normalize(Encoding.UTF8.GetString(stream.ToArray())) + "\n";
    }
}

