namespace BatchRenameStudio.Cli;

/// <summary>Minimal <c>--flag value</c> parser. Flags are matched case-insensitively.</summary>
internal sealed class CommandLine
{
    private readonly Dictionary<string, string?> _values = new(StringComparer.OrdinalIgnoreCase);
    private readonly List<string> _positional = new();

    private CommandLine() { }

    public static CommandLine Parse(string[] args)
    {
        var cl = new CommandLine();
        for (int i = 0; i < args.Length; i++)
        {
            string arg = args[i];
            if (arg.StartsWith("--", StringComparison.Ordinal) || arg.StartsWith("/", StringComparison.Ordinal))
            {
                string key = arg.TrimStart('-', '/');
                int eq = key.IndexOf('=');
                if (eq >= 0)
                {
                    cl._values[key.Substring(0, eq)] = key.Substring(eq + 1);
                    continue;
                }

                string? value = null;
                if (i + 1 < args.Length && !args[i + 1].StartsWith("--", StringComparison.Ordinal))
                {
                    value = args[i + 1];
                    i++;
                }
                cl._values[key] = value;
            }
            else
            {
                cl._positional.Add(arg);
            }
        }
        return cl;
    }

    public bool HasFlag(string name) => _values.ContainsKey(name);

    public string? Value(string name) => _values.TryGetValue(name, out string? v) ? v : null;

    public IReadOnlyList<string> Positional => _positional;
}

