using BatchRenameStudio.Cli;
using BatchRenameStudio.Gui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        var cl = CommandLine.Parse(args);

        if (cl.HasFlag("plan"))
        {
            ConsoleBridge.Ensure();
            return PlanCommand.Run(cl);
        }

        if (cl.HasFlag("help") || cl.HasFlag("h") || cl.HasFlag("?"))
        {
            ConsoleBridge.Ensure();
            Console.Out.WriteLine(PlanCommand.UsageText);
            return PlanCommand.ExitSuccess;
        }

        ApplicationConfiguration.Initialize();
        Application.Run(new MainForm(cl.Value("dir")));
        return PlanCommand.ExitSuccess;
    }
}

