using System.ComponentModel;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Gui;

/// <summary>
/// Single window: folder on top, rule editor on the left, live preview on the right.
/// The preview is produced by <see cref="RenameEngine"/> — the same code path the headless
/// --plan mode uses — so what is shown is exactly what would be written to plan.json.
/// </summary>
public sealed class MainForm : Form
{
    private readonly RuleSet _rules = new();
    private readonly Stack<RenameBatch> _undoStack = new();

    private IReadOnlyList<SourceFile> _files = Array.Empty<SourceFile>();
    private PlanDocument? _plan;
    private bool _suspendPreview;

    // -- top bar
    private readonly TextBox _folderBox = new();
    private readonly Button _browseButton = new();
    private readonly Button _refreshButton = new();

    // -- rule editor
    private readonly ComboBox _applyToBox = new();
    private readonly ComboBox _sortBox = new();
    private readonly ListBox _stepList = new();
    private readonly PropertyGrid _stepGrid = new();
    private readonly Button _addButton = new();
    private readonly Button _removeButton = new();
    private readonly Button _upButton = new();
    private readonly Button _downButton = new();
    private readonly Button _duplicateButton = new();
    private readonly ContextMenuStrip _addMenu = new();

    // -- preview
    private readonly ListView _preview = new();
    private readonly CheckBox _onlyChangesBox = new();

    // -- actions and status
    private readonly Button _applyButton = new();
    private readonly Button _undoButton = new();
    private readonly Button _loadRulesButton = new();
    private readonly Button _saveRulesButton = new();
    private readonly Button _exportPlanButton = new();
    private readonly StatusStrip _status = new();
    private readonly ToolStripStatusLabel _summaryLabel = new();
    private readonly ToolStripStatusLabel _messageLabel = new();

    private static readonly Color OkColor = Color.FromArgb(0, 110, 40);
    private static readonly Color CollisionColor = Color.FromArgb(180, 60, 0);
    private static readonly Color InvalidColor = Color.FromArgb(180, 0, 0);
    private static readonly Color UnchangedColor = Color.FromArgb(120, 120, 120);

    public MainForm(string? initialDirectory)
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(940, 560);
        Size = new Size(1180, 720);
        StartPosition = FormStartPosition.CenterScreen;
        AutoScaleMode = AutoScaleMode.Dpi;
        Font = new Font("Segoe UI", 9F);

        BuildLayout();
        WireEvents();
        SeedDefaultRules();

        string start = !string.IsNullOrWhiteSpace(initialDirectory)
            ? initialDirectory!
            : Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);
        _folderBox.Text = start;
        BeginInvoke(new Action(() => LoadFolder(start, quiet: true)));
    }

    // ------------------------------------------------------------- layout

    private void BuildLayout()
    {
        var root = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
            Padding = new Padding(10, 8, 10, 4),
        };
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        root.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));

        root.Controls.Add(BuildFolderBar(), 0, 0);

        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            SplitterDistance = 420,
            SplitterWidth = 8,
        };
        split.Panel1MinSize = 340;
        split.Panel2MinSize = 380;
        split.Panel1.Controls.Add(BuildRuleEditor());
        split.Panel2.Controls.Add(BuildPreview());
        root.Controls.Add(split, 0, 1);

        root.Controls.Add(BuildActionBar(), 0, 2);

        _summaryLabel.Spring = false;
        _summaryLabel.Text = "no folder loaded";
        _messageLabel.Spring = true;
        _messageLabel.TextAlign = ContentAlignment.MiddleLeft;
        _status.Items.Add(_summaryLabel);
        _status.Items.Add(new ToolStripSeparator());
        _status.Items.Add(_messageLabel);
        _status.SizingGrip = true;

        Controls.Add(root);
        Controls.Add(_status);

        // Split distance can only be set once the control has a size.
        Shown += (_, _) => { try { split.SplitterDistance = 430; } catch (InvalidOperationException) { } };
    }

    private Control BuildFolderBar()
    {
        var panel = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 4,
            RowCount = 1,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            Margin = new Padding(0, 0, 0, 6),
        };
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));

        var label = new Label { Text = "Folder", AutoSize = true, Anchor = AnchorStyles.Left, Margin = new Padding(0, 7, 8, 0) };
        _folderBox.Dock = DockStyle.Fill;
        _folderBox.Margin = new Padding(0, 3, 6, 3);

        _browseButton.Text = "Browse…";
        _browseButton.AutoSize = true;
        _browseButton.Margin = new Padding(0, 2, 6, 2);

        _refreshButton.Text = "Rescan";
        _refreshButton.AutoSize = true;
        _refreshButton.Margin = new Padding(0, 2, 0, 2);

        panel.Controls.Add(label, 0, 0);
        panel.Controls.Add(_folderBox, 1, 0);
        panel.Controls.Add(_browseButton, 2, 0);
        panel.Controls.Add(_refreshButton, 3, 0);
        return panel;
    }

    private Control BuildRuleEditor()
    {
        var host = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 4,
            Margin = new Padding(0, 0, 4, 0),
        };
        host.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        host.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        host.RowStyles.Add(new RowStyle(SizeType.Percent, 55));
        host.RowStyles.Add(new RowStyle(SizeType.Percent, 45));

        // scope row
        var scope = new FlowLayoutPanel { Dock = DockStyle.Fill, AutoSize = true, WrapContents = false, Margin = new Padding(0) };
        scope.Controls.Add(new Label { Text = "Apply to", AutoSize = true, Margin = new Padding(0, 8, 6, 0) });
        _applyToBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToBox.Items.AddRange(new object[] { "name", "nameAndExtension" });
        _applyToBox.SelectedIndex = 0;
        _applyToBox.Width = 150;
        _applyToBox.Margin = new Padding(0, 4, 18, 4);
        scope.Controls.Add(_applyToBox);
        scope.Controls.Add(new Label { Text = "Order", AutoSize = true, Margin = new Padding(0, 8, 6, 0) });
        _sortBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortBox.Items.AddRange(new object[] { "name", "created", "modified" });
        _sortBox.SelectedIndex = 0;
        _sortBox.Width = 110;
        _sortBox.Margin = new Padding(0, 4, 0, 4);
        scope.Controls.Add(_sortBox);
        host.Controls.Add(scope, 0, 0);

        // step toolbar
        var tools = new FlowLayoutPanel { Dock = DockStyle.Fill, AutoSize = true, WrapContents = false, Margin = new Padding(0, 2, 0, 4) };
        ConfigureSmallButton(_addButton, "Add step ▾");
        ConfigureSmallButton(_duplicateButton, "Duplicate");
        ConfigureSmallButton(_removeButton, "Remove");
        ConfigureSmallButton(_upButton, "▲");
        ConfigureSmallButton(_downButton, "▼");
        tools.Controls.Add(_addButton);
        tools.Controls.Add(_duplicateButton);
        tools.Controls.Add(_removeButton);
        tools.Controls.Add(_upButton);
        tools.Controls.Add(_downButton);
        host.Controls.Add(tools, 0, 1);

        _stepList.Dock = DockStyle.Fill;
        _stepList.IntegralHeight = false;
        _stepList.Margin = new Padding(0, 0, 0, 6);
        host.Controls.Add(_stepList, 0, 2);

        _stepGrid.Dock = DockStyle.Fill;
        _stepGrid.ToolbarVisible = false;
        _stepGrid.HelpVisible = true;
        _stepGrid.PropertySort = PropertySort.NoSort;
        _stepGrid.Margin = new Padding(0);
        host.Controls.Add(_stepGrid, 0, 3);

        foreach (var (text, factory) in StepFactories)
        {
            var entry = new ToolStripMenuItem(text);
            entry.Click += (_, _) => AddStep(factory());
            _addMenu.Items.Add(entry);
        }

        return host;
    }

    private static void ConfigureSmallButton(Button button, string text)
    {
        button.Text = text;
        button.AutoSize = true;
        button.Margin = new Padding(0, 0, 6, 0);
    }

    private static IEnumerable<(string Text, Func<RuleStep> Factory)> StepFactories => new (string, Func<RuleStep>)[]
    {
        ("Replace text…", () => new ReplaceStep()),
        ("Insert text…", () => new InsertStep { Text = "new_" }),
        ("Remove characters…", () => new RemoveStep { From = 0, Count = 1 }),
        ("Numbering sequence…", () => new SequenceStep()),
        ("Change case…", () => new CaseStep()),
        ("Change extension…", () => new ExtensionStep()),
    };

    private Control BuildPreview()
    {
        var host = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 2,
            Margin = new Padding(4, 0, 0, 0),
        };
        host.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        host.RowStyles.Add(new RowStyle(SizeType.Percent, 100));

        var bar = new FlowLayoutPanel { Dock = DockStyle.Fill, AutoSize = true, WrapContents = false, Margin = new Padding(0, 2, 0, 4) };
        bar.Controls.Add(new Label { Text = "Preview", AutoSize = true, Margin = new Padding(0, 6, 16, 0), Font = new Font("Segoe UI", 9F, FontStyle.Bold) });
        _onlyChangesBox.Text = "Hide unchanged";
        _onlyChangesBox.AutoSize = true;
        _onlyChangesBox.Margin = new Padding(0, 4, 0, 0);
        bar.Controls.Add(_onlyChangesBox);
        host.Controls.Add(bar, 0, 0);

        _preview.Dock = DockStyle.Fill;
        _preview.View = View.Details;
        _preview.FullRowSelect = true;
        _preview.HideSelection = false;
        _preview.MultiSelect = true;
        _preview.UseCompatibleStateImageBehavior = false;
        _preview.Columns.Add("#", 40, HorizontalAlignment.Right);
        _preview.Columns.Add("Original", 230);
        _preview.Columns.Add("Proposed", 250);
        _preview.Columns.Add("Status", 80);
        _preview.Columns.Add("Reason", 220);
        host.Controls.Add(_preview, 0, 1);

        return host;
    }

    private Control BuildActionBar()
    {
        var bar = new FlowLayoutPanel
        {
            Dock = DockStyle.Fill,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            WrapContents = false,
            FlowDirection = FlowDirection.LeftToRight,
            Margin = new Padding(0, 6, 0, 0),
        };

        _applyButton.Text = "Apply rename";
        _applyButton.AutoSize = true;
        _applyButton.Padding = new Padding(10, 4, 10, 4);
        _applyButton.Margin = new Padding(0, 0, 8, 0);
        _applyButton.Font = new Font("Segoe UI", 9F, FontStyle.Bold);

        _undoButton.Text = "Undo last";
        _undoButton.AutoSize = true;
        _undoButton.Enabled = false;
        _undoButton.Padding = new Padding(8, 4, 8, 4);
        _undoButton.Margin = new Padding(0, 0, 24, 0);

        _loadRulesButton.Text = "Load rules…";
        _saveRulesButton.Text = "Save rules…";
        _exportPlanButton.Text = "Export plan.json…";
        foreach (var b in new[] { _loadRulesButton, _saveRulesButton, _exportPlanButton })
        {
            b.AutoSize = true;
            b.Padding = new Padding(6, 3, 6, 3);
            b.Margin = new Padding(0, 0, 8, 0);
        }

        bar.Controls.Add(_applyButton);
        bar.Controls.Add(_undoButton);
        bar.Controls.Add(_loadRulesButton);
        bar.Controls.Add(_saveRulesButton);
        bar.Controls.Add(_exportPlanButton);
        return bar;
    }

    // ------------------------------------------------------------- events

    private void WireEvents()
    {
        _browseButton.Click += (_, _) => BrowseForFolder();
        _refreshButton.Click += (_, _) => LoadFolder(_folderBox.Text, quiet: false);
        _folderBox.KeyDown += (_, e) =>
        {
            if (e.KeyCode == Keys.Enter)
            {
                e.SuppressKeyPress = true;
                LoadFolder(_folderBox.Text, quiet: false);
            }
        };

        _applyToBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = _applyToBox.SelectedIndex == 1 ? ApplyTo.NameAndExtension : ApplyTo.Name;
            RefreshPreview();
        };
        _sortBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = _sortBox.SelectedIndex switch
            {
                1 => SortMode.Created,
                2 => SortMode.Modified,
                _ => SortMode.Name,
            };
            RefreshPreview();
        };

        _addButton.Click += (_, _) => _addMenu.Show(_addButton, new Point(0, _addButton.Height));
        _removeButton.Click += (_, _) => RemoveSelectedStep();
        _duplicateButton.Click += (_, _) => DuplicateSelectedStep();
        _upButton.Click += (_, _) => MoveSelectedStep(-1);
        _downButton.Click += (_, _) => MoveSelectedStep(+1);

        _stepList.SelectedIndexChanged += (_, _) =>
        {
            _stepGrid.SelectedObject = _stepList.SelectedIndex >= 0 ? _rules.Steps[_stepList.SelectedIndex] : null;
            UpdateStepButtons();
        };
        _stepGrid.PropertyValueChanged += (_, _) =>
        {
            RebuildStepList(_stepList.SelectedIndex);
            RefreshPreview();
        };

        _onlyChangesBox.CheckedChanged += (_, _) => PopulatePreview();

        _applyButton.Click += (_, _) => ApplyRename();
        _undoButton.Click += (_, _) => UndoLast();
        _loadRulesButton.Click += (_, _) => LoadRules();
        _saveRulesButton.Click += (_, _) => SaveRules();
        _exportPlanButton.Click += (_, _) => ExportPlan();
    }

    private void SeedDefaultRules()
    {
        _suspendPreview = true;
        _rules.Steps.Add(new SequenceStep { Pattern = "{n:000}_", Start = 1, Step = 1, Position = SequencePosition.Prefix });
        RebuildStepList(0);
        _suspendPreview = false;
    }

    // ------------------------------------------------------------- folder

    private void BrowseForFolder()
    {
        using var dialog = new FolderBrowserDialog
        {
            Description = "Pick the folder to rename in (files directly inside it only)",
            UseDescriptionForTitle = true,
            ShowNewFolderButton = false,
        };
        if (Directory.Exists(_folderBox.Text)) dialog.SelectedPath = _folderBox.Text;
        if (dialog.ShowDialog(this) == DialogResult.OK)
        {
            _folderBox.Text = dialog.SelectedPath;
            LoadFolder(dialog.SelectedPath, quiet: false);
        }
    }

    private void LoadFolder(string directory, bool quiet)
    {
        try
        {
            _files = FileScanner.Scan(directory);
            SetMessage($"{_files.Count} file(s) in folder.", error: false);
            RefreshPreview();
        }
        catch (RuleException ex)
        {
            _files = Array.Empty<SourceFile>();
            _plan = null;
            _preview.Items.Clear();
            _summaryLabel.Text = "no folder loaded";
            SetMessage(ex.Message, error: true);
            if (!quiet) SystemSounds.OnError();
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            _files = Array.Empty<SourceFile>();
            _plan = null;
            _preview.Items.Clear();
            SetMessage(ex.Message, error: true);
        }
    }

    // ------------------------------------------------------------- steps

    private void AddStep(RuleStep step)
    {
        _rules.Steps.Add(step);
        RebuildStepList(_rules.Steps.Count - 1);
        RefreshPreview();
    }

    private void RemoveSelectedStep()
    {
        int index = _stepList.SelectedIndex;
        if (index < 0) return;
        _rules.Steps.RemoveAt(index);
        RebuildStepList(Math.Min(index, _rules.Steps.Count - 1));
        RefreshPreview();
    }

    private void DuplicateSelectedStep()
    {
        int index = _stepList.SelectedIndex;
        if (index < 0) return;
        _rules.Steps.Insert(index + 1, _rules.Steps[index].Clone());
        RebuildStepList(index + 1);
        RefreshPreview();
    }

    private void MoveSelectedStep(int delta)
    {
        int index = _stepList.SelectedIndex;
        int target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count) return;
        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        RebuildStepList(target);
        RefreshPreview();
    }

    private void RebuildStepList(int selectIndex)
    {
        _stepList.BeginUpdate();
        _stepList.Items.Clear();
        for (int i = 0; i < _rules.Steps.Count; i++)
        {
            _stepList.Items.Add($"{i + 1}.  {_rules.Steps[i].Describe()}");
        }
        _stepList.EndUpdate();

        if (_rules.Steps.Count == 0)
        {
            _stepList.SelectedIndex = -1;
            _stepGrid.SelectedObject = null;
        }
        else
        {
            int index = Math.Clamp(selectIndex, 0, _rules.Steps.Count - 1);
            _stepList.SelectedIndex = index;
            _stepGrid.SelectedObject = _rules.Steps[index];
        }
        UpdateStepButtons();
    }

    private void UpdateStepButtons()
    {
        int index = _stepList.SelectedIndex;
        bool has = index >= 0;
        _removeButton.Enabled = has;
        _duplicateButton.Enabled = has;
        _upButton.Enabled = has && index > 0;
        _downButton.Enabled = has && index < _rules.Steps.Count - 1;
    }

    // ------------------------------------------------------------- preview

    private void RefreshPreview()
    {
        if (_suspendPreview) return;

        try
        {
            _plan = RenameEngine.BuildPlan(_files, _rules);
            PopulatePreview();
            var s = _plan.Summary;
            _summaryLabel.Text = $"total {s.Total}   ok {s.Ok}   collision {s.Collision}   unchanged {s.Unchanged}   invalid {s.Invalid}";
            _applyButton.Enabled = s.Ok > 0;
            if (_messageLabel.ForeColor == Color.Firebrick) SetMessage("", error: false);
        }
        catch (RuleException ex)
        {
            _plan = null;
            _preview.Items.Clear();
            _applyButton.Enabled = false;
            _summaryLabel.Text = "rule error";
            SetMessage(ex.Message, error: true);
        }
    }

    private void PopulatePreview()
    {
        _preview.BeginUpdate();
        _preview.Items.Clear();
        if (_plan is not null)
        {
            bool hideUnchanged = _onlyChangesBox.Checked;
            int number = 0;
            foreach (var item in _plan.Items)
            {
                number++;
                if (hideUnchanged && item.Status == PlanStatus.Unchanged) continue;

                var row = new ListViewItem(number.ToString());
                row.SubItems.Add(item.Original);
                row.SubItems.Add(item.Proposed);
                row.SubItems.Add(item.Status);
                row.SubItems.Add(item.Reason);
                row.ForeColor = item.Status switch
                {
                    PlanStatus.Ok => OkColor,
                    PlanStatus.Collision => CollisionColor,
                    PlanStatus.Invalid => InvalidColor,
                    _ => UnchangedColor,
                };
                _preview.Items.Add(row);
            }
        }
        _preview.EndUpdate();
    }

    private void SetMessage(string text, bool error)
    {
        _messageLabel.Text = text;
        _messageLabel.ForeColor = error ? Color.Firebrick : SystemColors.ControlText;
    }

    // ------------------------------------------------------------- actions

    private void ApplyRename()
    {
        string directory = _folderBox.Text;
        if (!Directory.Exists(directory))
        {
            MessageBox.Show(this, "That folder no longer exists.", "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Warning);
            return;
        }

        // Re-scan first: the folder may have changed since the preview was built.
        LoadFolder(directory, quiet: false);
        if (_plan is null) return;

        var s = _plan.Summary;
        if (s.Ok == 0)
        {
            MessageBox.Show(this, "Nothing to rename — no item has status \"ok\".", "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        string blocked = s.Collision + s.Invalid > 0
            ? $"\n\n{s.Collision} collision and {s.Invalid} invalid item(s) will be left untouched."
            : "";
        var answer = MessageBox.Show(this,
            $"Rename {s.Ok} file(s) in\n{directory}?{blocked}",
            "Confirm rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Question);
        if (answer != DialogResult.OK) return;

        var outcome = RenameExecutor.Apply(directory, _plan, DateTime.UtcNow);
        if (outcome.Batch is { Operations.Count: > 0 })
        {
            _undoStack.Push(outcome.Batch);
            _undoButton.Enabled = true;
        }

        LoadFolder(directory, quiet: true);

        if (outcome.Errors.Count > 0)
        {
            MessageBox.Show(this,
                $"Renamed {outcome.Renamed} file(s). {outcome.Errors.Count} failed:\n\n" +
                string.Join("\n", outcome.Errors.Take(15)),
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
        SetMessage($"Renamed {outcome.Renamed} file(s). Undo is available.", error: false);
    }

    private void UndoLast()
    {
        if (_undoStack.Count == 0) return;
        var batch = _undoStack.Pop();
        var outcome = RenameExecutor.Undo(batch);
        _undoButton.Enabled = _undoStack.Count > 0;

        LoadFolder(_folderBox.Text, quiet: true);

        if (outcome.Errors.Count > 0)
        {
            MessageBox.Show(this,
                $"Reverted {outcome.Renamed} of {batch.Operations.Count} rename(s). Problems:\n\n" +
                string.Join("\n", outcome.Errors.Take(15)),
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
        SetMessage($"Undid {outcome.Renamed} rename(s) from {batch.Label}.", error: false);
    }

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load rules",
            Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            var loaded = RulesJson.Load(dialog.FileName);
            _suspendPreview = true;
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);
            _applyToBox.SelectedIndex = loaded.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
            _sortBox.SelectedIndex = loaded.Sort switch
            {
                SortMode.Created => 1,
                SortMode.Modified => 2,
                _ => 0,
            };
            RebuildStepList(0);
            _suspendPreview = false;
            RefreshPreview();
            SetMessage($"Loaded {Path.GetFileName(dialog.FileName)}.", error: false);
        }
        catch (RuleException ex)
        {
            _suspendPreview = false;
            MessageBox.Show(this, ex.Message, "Cannot load rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save rules",
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            RulesJson.Save(dialog.FileName, _rules);
            SetMessage($"Saved {Path.GetFileName(dialog.FileName)}.", error: false);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            MessageBox.Show(this, ex.Message, "Cannot save rules", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }

    private void ExportPlan()
    {
        if (_plan is null)
        {
            MessageBox.Show(this, "There is no plan to export yet.", "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        using var dialog = new SaveFileDialog
        {
            Title = "Export plan",
            Filter = "Plans (*.json)|*.json",
            FileName = "plan.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            PlanJson.Save(dialog.FileName, _plan);
            SetMessage($"Exported {Path.GetFileName(dialog.FileName)}.", error: false);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            MessageBox.Show(this, ex.Message, "Cannot export plan", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        }
    }
}

