/// <summary>
/// Console plumbing for a single executable that is both a CLI and a GUI.
/// <para>
/// The project is built for the console subsystem so that shells actually wait for it and
/// propagate its exit code; <see cref="ReleaseForGui"/> then drops the console before the window
/// opens. <see cref="Ensure"/> covers the reverse case — a build that ends up without a usable
/// stdout handle attaches to the parent console. Both must run before anything touches
/// <see cref="Console"/>.
/// </para>
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const uint AttachParentProcess = 0xFFFFFFFF;
    private const int SwHide = 0;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(uint dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool FreeConsole();

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetConsoleWindow();

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint GetConsoleProcessList(uint[] processList, uint count);

    [DllImport("user32.dll")]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    /// <summary>
    /// Detaches the GUI process from its console. If this process is the only one attached the
    /// console belongs to us (double clicked from Explorer) and is hidden first; if a shell is
    /// also attached its window is left alone.
    /// </summary>
    public static void ReleaseForGui()
    {
        try
        {
            IntPtr window = GetConsoleWindow();
            if (window == IntPtr.Zero) return;

            var owners = new uint[4];
            uint attached = GetConsoleProcessList(owners, (uint)owners.Length);
            if (attached == 1) ShowWindow(window, SwHide);

            FreeConsole();
        }
        catch (DllNotFoundException)
        {
            // Not fatal: worst case a console window stays open behind the GUI.
        }
    }

