using System.Runtime.InteropServices;

namespace BatchRenameStudio.Cli;

/// <summary>
/// This is a WinExe (no console subsystem), which is what keeps the GUI from flashing a black
/// window. When stdout is redirected the inherited handle works as is; when the tool is typed at
/// an interactive prompt there is no handle at all, so we attach to the parent console first.
/// Must run before anything touches <see cref="Console"/>.
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const uint AttachParentProcess = 0xFFFFFFFF;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(uint dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    public static void Ensure()
    {
        IntPtr handle = GetStdHandle(StdOutputHandle);
        bool hasStdOut = handle != IntPtr.Zero && handle != new IntPtr(-1);
        if (hasStdOut) return; // redirected to a pipe or file: nothing to do

        if (!AttachConsole(AttachParentProcess)) return; // launched detached: output is discarded

        try
        {
            var stdout = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true };
            Console.SetOut(stdout);
            var stderr = new StreamWriter(Console.OpenStandardError()) { AutoFlush = true };
            Console.SetError(stderr);
        }
        catch (IOException)
        {
            // Leave the default (null) writers in place.
        }
    }
}

using BatchRenameStudio.Cli;
using BatchRenameStudio.Gui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        var cl = CommandLine.Parse(args);

        if (cl.HasFlag("plan"))
        {
            ConsoleBridge.Ensure();
            return PlanCommand.Run(cl);
        }

        if (cl.HasFlag("help") || cl.HasFlag("h") || cl.HasFlag("?"))
        {
            ConsoleBridge.Ensure();
            Console.Out.WriteLine(PlanCommand.UsageText);
            return PlanCommand.ExitSuccess;
        }

        ApplicationConfiguration.Initialize();
        Application.Run(new MainForm(cl.Value("dir")));
        return PlanCommand.ExitSuccess;
    }
}

