using System.Globalization;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Reader for the history files <see cref="RenameExecutor"/> writes after every apply.</summary>
public static class JournalJson
{
    public static RenameBatch Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            throw new RuleException($"Cannot read history file \"{path}\": {ex.Message}", ex);
        }

        try
        {
            using var doc = JsonDocument.Parse(text);
            var root = doc.RootElement;
            string directory = root.GetProperty("directory").GetString()
                               ?? throw new RuleException("History file has no \"directory\".");
            DateTime timestamp = root.TryGetProperty("timestampUtc", out var ts) && ts.ValueKind == JsonValueKind.String
                ? DateTime.Parse(ts.GetString()!, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind)
                : DateTime.UtcNow;

            var operations = new List<RenameOperation>();
            if (root.TryGetProperty("operations", out var ops) && ops.ValueKind == JsonValueKind.Array)
            {
                foreach (var op in ops.EnumerateArray())
                {
                    string from = op.GetProperty("from").GetString() ?? "";
                    string to = op.GetProperty("to").GetString() ?? "";
                    if (from.Length > 0 && to.Length > 0) operations.Add(new RenameOperation(from, to));
                }
            }
            return new RenameBatch(directory, timestamp, operations);
        }
        catch (Exception ex) when (ex is JsonException or KeyNotFoundException or FormatException)
        {
            throw new RuleException($"History file \"{path}\" is malformed: {ex.Message}", ex);
        }
    }

    /// <summary>Newest history file first.</summary>
    public static IReadOnlyList<string> ListJournals()
    {
        if (!Directory.Exists(RenameExecutor.JournalDirectory)) return Array.Empty<string>();
        return Directory.GetFiles(RenameExecutor.JournalDirectory, "*.json")
            .OrderByDescending(p => p, StringComparer.Ordinal)
            .ToList();
    }
}

