using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Scripting companions to the plan mode. Not part of the fixed contract — they exist so the
/// rename and undo paths the GUI buttons use can be exercised without a human in the loop.
/// <code>
/// BatchRenameStudio.exe --apply --dir &lt;folder&gt; --rules &lt;rules.json&gt; [--out &lt;plan.json&gt;]
/// BatchRenameStudio.exe --undo  [&lt;history.json&gt;]
/// </code>
/// </summary>
internal static class ApplyCommand
{
    public static int RunApply(CommandLine cl)
    {
        string? dir = cl.Value("dir");
        string? rulesPath = cl.Value("rules");
        if (string.IsNullOrWhiteSpace(dir) || string.IsNullOrWhiteSpace(rulesPath))
        {
            Console.Error.WriteLine("error: --apply needs --dir and --rules.");
            return PlanCommand.ExitUsage;
        }

        try
        {
            var rules = RulesJson.Load(rulesPath);
            var plan = RenameEngine.BuildPlan(FileScanner.Scan(dir), rules);

            string? outPath = cl.Value("out");
            if (!string.IsNullOrWhiteSpace(outPath)) PlanJson.Save(outPath, plan);

            var outcome = RenameExecutor.Apply(dir, plan, DateTime.UtcNow);
            foreach (string error in outcome.Errors) Console.Error.WriteLine("warning: " + error);

            Console.Out.WriteLine(
                $"renamed={outcome.Renamed} skipped={outcome.Skipped} failed={outcome.Errors.Count} " +
                plan.Summary.ToSummaryLine());
            return outcome.Errors.Count == 0 ? PlanCommand.ExitSuccess : PlanCommand.ExitFailed;
        }
        catch (RuleException ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return PlanCommand.ExitFailed;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return PlanCommand.ExitFailed;
        }
    }

    public static int RunUndo(CommandLine cl)
    {
        string? journalPath = cl.Value("undo");
        if (string.IsNullOrWhiteSpace(journalPath))
        {
            journalPath = JournalJson.ListJournals().FirstOrDefault();
            if (journalPath is null)
            {
                Console.Error.WriteLine($"error: no history files in {RenameExecutor.JournalDirectory}.");
                return PlanCommand.ExitFailed;
            }
        }

        try
        {
            var batch = JournalJson.Load(journalPath);
            var outcome = RenameExecutor.Undo(batch);
            foreach (string error in outcome.Errors) Console.Error.WriteLine("warning: " + error);
            Console.Out.WriteLine($"reverted={outcome.Renamed} of={batch.Operations.Count} failed={outcome.Errors.Count}");
            return outcome.Errors.Count == 0 ? PlanCommand.ExitSuccess : PlanCommand.ExitFailed;
        }
        catch (RuleException ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return PlanCommand.ExitFailed;
        }
    }
}

