using BatchRenameStudio.Cli;
using BatchRenameStudio.Gui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        var cl = CommandLine.Parse(args);

        if (cl.HasFlag("plan"))
        {
            ConsoleBridge.Ensure();
            return PlanCommand.Run(cl);
        }

        if (cl.HasFlag("help") || cl.HasFlag("h") || cl.HasFlag("?"))
        {
            ConsoleBridge.Ensure();
            Console.Out.WriteLine(PlanCommand.UsageText);
            return PlanCommand.ExitSuccess;
        }

        ConsoleBridge.ReleaseForGui();
        ApplicationConfiguration.Initialize();
        Application.Run(new MainForm(cl.Value("dir")));
        return PlanCommand.ExitSuccess;
    }
}

using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The headless contract:
/// <code>BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;</code>
/// Exit 0 on success, one summary line on stdout, nothing renamed.
/// </summary>
internal static class PlanCommand
{
    public const int ExitSuccess = 0;
    public const int ExitUsage = 2;
    public const int ExitFailed = 3;

    public static int Run(CommandLine cl)
    {
        string? dir = cl.Value("dir");
        string? rulesPath = cl.Value("rules");
        string? outPath = cl.Value("out");

        var missing = new List<string>();
        if (string.IsNullOrWhiteSpace(dir)) missing.Add("--dir");
        if (string.IsNullOrWhiteSpace(rulesPath)) missing.Add("--rules");
        if (string.IsNullOrWhiteSpace(outPath)) missing.Add("--out");
        if (missing.Count > 0)
        {
            Console.Error.WriteLine($"error: missing required argument(s): {string.Join(", ", missing)}");
            Console.Error.WriteLine(UsageText);
            return ExitUsage;
        }

        try
        {
            var rules = RulesJson.Load(rulesPath!);
            var files = FileScanner.Scan(dir!);
            var plan = RenameEngine.BuildPlan(files, rules);
            PlanJson.Save(outPath!, plan);

            // The one and only line this mode is allowed to put on stdout.
            Console.Out.WriteLine(plan.Summary.ToSummaryLine());
            Console.Out.Flush();
            return ExitSuccess;
        }
        catch (RuleException ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return ExitFailed;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or NotSupportedException)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return ExitFailed;
        }
    }

    public const string UsageText = """
        Batch Rename Studio

          BatchRenameStudio.exe
              Starts the graphical tool.

          BatchRenameStudio.exe --dir <folder>
              Starts the graphical tool with that folder already loaded.

          BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>
              Headless preview. Writes plan.json (UTF-8, no BOM), prints one summary line,
              and renames nothing. Exit code 0 on success, 2 on a usage error, 3 on failure.
        """;
}

